import capabilities from "../../../contracts/capabilities-v1.json";

// The API's registries and refusal list, generated by api/scripts/export_capabilities.py.
export type LayerKind = keyof typeof capabilities.layers;
export type SummaryKey = keyof typeof capabilities.summaries;
export type RefusalCode = keyof typeof capabilities.refusals;

type Words = { en: string; zh: string };
type LayerCapability = {
  title: Words; short: Words; options: string[]; roles: string[]; xAxis: string; limits: Record<string, number>;
};

// A kind this version does not know (a project saved by a later one) reads as undefined.
export const layers: Record<LayerKind, LayerCapability> & Record<string, LayerCapability | undefined> = capabilities.layers;
export const layerKinds = Object.keys(capabilities.layers) as [LayerKind, ...LayerKind[]];
export const summaries: Record<SummaryKey, { label: Words }> = capabilities.summaries;
export const summaryKeys = Object.keys(capabilities.summaries) as SummaryKey[];
// The values each refusal's text needs.
export const refusals: Record<RefusalCode, string[]> & Record<string, string[] | undefined> = capabilities.refusals;
